<script setup lang="ts">
import { computed, reactive, ref } from 'vue'; import { Boxes, MapPin, Package, UserRound } from 'lucide-vue-next'; import type { LongProjectAsset, LongProjectAssetType, LongProjectAssetVariant, LongProjectChapterAsset } from '@comic/types';
type StateCard = { entry: LongProjectChapterAsset; asset: LongProjectAsset; variant?: LongProjectAssetVariant; imageUrl?: string }; type SplitPayload = { assetId: string; variantId: string; name: string; description: string; imagePrompt: string };
const props = defineProps<{ entries: LongProjectChapterAsset[]; assets: LongProjectAsset[] }>(); const emit = defineEmits<{ (event: 'merge-variants', value: { assetId: string; sourceVariantIds: string[]; targetVariantId: string }): void; (event: 'split-variant', value: SplitPayload): void }>(); const detailItem = ref<StateCard | null>(null); const mergeIdsArray = ref<string[]>([]); const splitOpen = ref(false); const splitForm = reactive({ name: '', description: '', imagePrompt: '' }); const meta = { character: { label: '人物', icon: UserRound, tone: 'text-cyan-400' }, scene: { label: '场景', icon: MapPin, tone: 'text-emerald-400' }, prop: { label: '道具', icon: Package, tone: 'text-amber-400' } };
const resolved = computed<StateCard[]>(() => { const cards: StateCard[] = []; for (const entry of props.entries) { const asset = props.assets.find(item => item.id === entry.assetId); if (!asset) continue; if (asset.variants.length) asset.variants.forEach(variant => cards.push({ entry, asset, variant, imageUrl: variant.referenceImageIds.find(isImageSource) })); else cards.push({ entry, asset }); } return cards }); const groups = computed(() => (Object.keys(meta) as LongProjectAssetType[]).map(type => ({ type, ...meta[type], items: resolved.value.filter(item => item.asset.type === type) }))); const mergeIds = computed(() => new Set(mergeIdsArray.value)); const detailMeta = computed(() => detailItem.value ? meta[detailItem.value.asset.type] : meta.character); function openDetail(item: StateCard) { detailItem.value = item; mergeIdsArray.value = []; splitOpen.value = false; splitForm.name = item.variant ? `${item.variant.name} · 新状态` : '新视觉状态'; splitForm.description = item.variant?.description || ''; splitForm.imagePrompt = item.variant?.imagePrompt || '' } function closeDetail() { detailItem.value = null }; function mergeDetailVariants() { const item = detailItem.value; const ids = mergeIdsArray.value; if (!item || ids.length < 2) return; emit('merge-variants', { assetId: item.asset.id, sourceVariantIds: ids.slice(1), targetVariantId: ids[0] }); mergeIdsArray.value = [ids[0]] }; function submitSplit() { const item = detailItem.value; if (!item || !splitForm.name.trim()) return; emit('split-variant', { assetId: item.asset.id, variantId: item.variant?.id || '', name: splitForm.name.trim(), description: splitForm.description.trim(), imagePrompt: splitForm.imagePrompt.trim() }); splitOpen.value = false }; function isImageSource(value: string) { return /^(https?:|data:|blob:|file:|\/)/i.test(value) }
</script>
<style scoped>
